#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Fix direct video framing: attach to the whole player (reliable hit-testing past the
stacked layers), ignore control clicks, block native video drag, and gate to the
EDITOR ONLY (not the deployed view)."""
import sys
SRC = "script.js"
c = open(SRC, encoding="utf-8").read()

OLD = (
"  function attachVideoFraming(){\n"
"    const v = el.coverVideo;\n"
"    if (!v) return;\n"
"    let dragging = false, sx = 0, sy = 0, sdx = 0, sdy = 0, wheelTimer = null;\n"
"    const framable = () => videoMediaActive() && !el.player.classList.contains('cinema') && !state.dragMode;\n"
"    v.addEventListener('pointerdown', (e) => {\n"
"      if (!framable()) return;\n"
"      dragging = true; sx = e.clientX; sy = e.clientY;\n"
"      sdx = getVarNum('--cover-dx'); sdy = getVarNum('--cover-dy');\n"
"      try { v.setPointerCapture(e.pointerId); } catch {}\n"
"      v.style.cursor = 'grabbing';\n"
"    });\n"
"    v.addEventListener('pointermove', (e) => {\n"
"      if (!dragging) return;\n"
"      setVarPx('--cover-dx', sdx + (e.clientX - sx));\n"
"      setVarPx('--cover-dy', sdy + (e.clientY - sy));\n"
"    });\n"
"    const end = (e) => {\n"
"      if (!dragging) return;\n"
"      dragging = false; v.style.cursor = '';\n"
"      try { v.releasePointerCapture(e.pointerId); } catch {}\n"
"      persistCoverTransform();\n"
"    };\n"
"    v.addEventListener('pointerup', end);\n"
"    v.addEventListener('pointercancel', end);\n"
"    v.addEventListener('wheel', (e) => {\n"
"      if (!framable()) return;\n"
"      e.preventDefault();\n"
"      const s = clamp(getVarNum('--cover-scale', 1) + (-e.deltaY * 0.0015), 0.5, 5);\n"
"      setVarNum('--cover-scale', s);\n"
"      if (el.coverZoom) el.coverZoom.value = String(s);\n"
"      if (el.coverZoomVal) el.coverZoomVal.textContent = s.toFixed(2) + '×';\n"
"      clearTimeout(wheelTimer); wheelTimer = setTimeout(persistCoverTransform, 250);\n"
"    }, { passive: false });\n"
"  }"
)

NEW = (
"  function attachVideoFraming(){\n"
"    if (!isEditorPage()) return;            // editor/backend only — never on the deployed view\n"
"    const v = el.coverVideo;\n"
"    if (!v) return;\n"
"    try { v.draggable = false; } catch {}   // stop the browser's native video drag\n"
"    const player = el.player;\n"
"    let dragging = false, sx = 0, sy = 0, sdx = 0, sdy = 0, wheelTimer = null;\n"
"    const framable = () => videoMediaActive() && !player.classList.contains('cinema') && !state.dragMode;\n"
"    // don't hijack clicks on the real controls (play / scrub / icons / volume / playhead)\n"
"    const onControl = (tgt) => !!(tgt && tgt.closest && (tgt.closest('.controls') || tgt.closest('.seeker') || tgt.closest('a') || tgt.closest('.volume-level') || tgt.closest('.info') || tgt.closest('.knob-overlay')));\n"
"    player.addEventListener('pointerdown', (e) => {\n"
"      if (!framable() || onControl(e.target)) return;\n"
"      dragging = true; sx = e.clientX; sy = e.clientY;\n"
"      sdx = getVarNum('--cover-dx'); sdy = getVarNum('--cover-dy');\n"
"      try { player.setPointerCapture(e.pointerId); } catch {}\n"
"      e.preventDefault();\n"
"    });\n"
"    player.addEventListener('pointermove', (e) => {\n"
"      if (!dragging) return;\n"
"      setVarPx('--cover-dx', sdx + (e.clientX - sx));\n"
"      setVarPx('--cover-dy', sdy + (e.clientY - sy));\n"
"    });\n"
"    const end = (e) => {\n"
"      if (!dragging) return;\n"
"      dragging = false;\n"
"      try { player.releasePointerCapture(e.pointerId); } catch {}\n"
"      persistCoverTransform();\n"
"    };\n"
"    player.addEventListener('pointerup', end);\n"
"    player.addEventListener('pointercancel', end);\n"
"    player.addEventListener('wheel', (e) => {\n"
"      if (!framable() || onControl(e.target)) return;\n"
"      e.preventDefault();\n"
"      const s = clamp(getVarNum('--cover-scale', 1) + (-e.deltaY * 0.0015), 0.5, 5);\n"
"      setVarNum('--cover-scale', s);\n"
"      if (el.coverZoom) el.coverZoom.value = String(s);\n"
"      if (el.coverZoomVal) el.coverZoomVal.textContent = s.toFixed(2) + '×';\n"
"      clearTimeout(wheelTimer); wheelTimer = setTimeout(persistCoverTransform, 250);\n"
"    }, { passive: false });\n"
"  }"
)

n = c.count(OLD)
if n != 1:
    print("ABORTED: expected 1, found %d" % n); sys.exit(1)
open(SRC, "w", encoding="utf-8").write(c.replace(OLD, NEW))
print("OK — video framing fixed (player-level, editor-only, controls excluded)")
